namespace MorningInk.Application.Publishing;

/// <summary>Where rendered issues are stored.</summary>
public interface IIssueFiles
{
    /// <summary>Full path for <paramref name="fileName"/> in the issue directory, which exists afterwards.</summary>
    /// <param name="fileName">A name generated by Morning Ink (issue id plus extension), never from content.</param>
    string PathFor(string fileName);
}
